import datetime,fcntl,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 plan=H/'cadence-discovery-frozen-plan-nov3.json';m=json.loads(plan.read_text());state=json.loads((H/'live-nov3-cadence-discovery-custody.json').read_text());a=json.loads((H/'live-nov3-cadence-discovery-independent-analysis.json').read_text());rows=list(a['rows'].values())
 assert sha(plan)==state['manifest_sha256'];bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad
 assert state['status']=='complete' and len(state['runs'])==12 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time']
 assert all(r['owned_descendants_remaining']==[] for r in rows)
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file());files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.exists() for p in files);assert not any(p.suffix in ['.log','.jsonl'] for p in files)
 arms={}
 for arm in ['native','periodic','once_positive','once_complete']:
  rr=[r for r in rows if r['arm']==arm];arms[arm]={'EOS':sum(r['natural_eos'] for r in rr),'generated_tokens':sum(r['tokens'] for r in rr),'hints':sum(r['cadence_receipt']['hint_rows'] for r in rr),'wait_groups':sum(r['cadence_receipt']['wait_groups'] for r in rr),'stop_markers':sum(r['cadence_receipt']['stop_markers'] for r in rr),'positive_acknowledgements':sum(r['cadence_receipt']['positive_acknowledgements'] for r in rr),'complete_acknowledgements':sum(r['cadence_receipt']['complete_acknowledgements'] for r in rr)}
 overlap=json.loads((H/'live-nov3-cadence-external-cpu-overlap.json').read_text())
 quality={'sample_path':'live-nov3-cadence-discovery-quality-samples.json','manually_inspected':8,'findings':['Both once variants repeat same astropy fenced definition on7703 (format violation), unsupported repository-structure correctness from directory listing, and broad environment-blocker inference from grep missing paths on8803.','Both once variants repeat material9901 timezone mistake: supplied source hardcodes UTC but output describes correct database-timezone conversion.'],'source_grounding':'Retained source issues/latest observations already reviewed in confirmation sample receipt; no model generation or external retrieval for review.','mechanical_inventory':{r['name']:r['service_format'] for r in rows},'degeneracy_screen_flags':sum(r['output_screen']['flagged'] for r in rows),'scope':'Small descriptive spot check, not accuracy score, equivalence, human productivity or autonomous task-success qualification.'}
 assessment={'schema':'astra-cadence-discovery-assessment-v1','plan_sha256':sha(plan),'all_12_eligible':all(r['eligible'] for r in rows),'natural_eos':sum(r['natural_eos'] for r in rows),'HTTP':{'attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)},'cadence_all_causal_source_and_stop_checks_pass':all(r['cadence_receipt']['qualified'] for r in rows),'arm_cadence_and_output_totals':arms,'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'first_admission_reconciles_all':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'store_accept_complete_balanced_all':all(r['store_balance']['balanced'] is True for r in rows),'explicit_store_failure_counter':'Unavailable, not assumed zero.','all_measurement_configurations_match':all(r['measurement']['matches_frozen_lean'] for r in rows),'optional_observer_counts_explicit_zero':all(all(r['measurement'][k]==0 for k in ['residency_samples','readmission_events','lookup_observer_events']) for r in rows),'comparisons':a['comparisons'],'resource_and_mechanism_rows':{r['name']:{k:r[k] for k in ['load_s','tokens','tokens_s','tokens_s_per_gib','ttft_ms','e2e_ms','resources','host_resources','thermal_clock_power','first_prefill_attribution','transfers','scheduler_counts','cadence_receipt']} for r in rows},'external_CPU_activity':overlap,'quality':quality,'production_endorsement':False,'judgment':'Neither once policy is a convincing broadly favorable production candidate from this screen. Once-positive largely recovers native-like behavior while discarding8803 periodic benefit; once-complete partially preserves that benefit but remains slower7703 and has9901 p95TTFT regression. Fewer advice RPCs alone do not establish better retention or net performance.','limitations':['One workflow perarm per spent partition, three rows of four-arm rotation; incomplete order balance, no inferential confirmation.','No performance outcome excluded or replaced, including disclosed startup CPU overlap.','Once-complete can have multiple positive partial acknowledgements; its at-most-one condition applies to complete qualifying ACK, not every positive partial ACK.','All policy source checks reconstruct actual prior completed model histories; no future private wait schedule is used by producer.','First-admission attribution is not cumulative physical GPU execution; native H2D totals reported separately.','Serving NVML7701.87–7703.87MiB, startup7953.87MiB; CPUKV1792MiB. No meaningful memory advantage from cadence.','System-wide swap/thermal/clock observations do not uniquely attribute cost or mechanism.','Material baseline model reasoning defects remain; human review required and productivity unmeasured.','4096identity registry saturation/continuous endurance unqualified.'],'next_step':'A separately frozen predicted-reuse ARC promotion screen is causally defensible if per-call actual T1-to-T2 counts are exposed, ownership/ghost-target/invalid-hint tests pass, all old/native controls retained, and no production claim precedes fresh quiet confirmation and endurance.'}
 write(H/'live-nov3-cadence-discovery-independent-assessment.json',assessment)
 inventory={'schema':'astra-cadence-discovery-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','pins_checked':len(m['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'reason':'All raw evidence, per-run archives, compressed logs and negative outcomes preserved for independent recomputation. No disposable downloads/worktrees/checkpoints/uncompressed logs/owned processes remain; prior/shared work untouched.'};write(H/'live-nov3-cadence-discovery-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':assessment['HTTP'],'arms':arms,'pins':len(m['file_pins']),'retained_bytes':inventory['retained_bytes'],'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
